-	0, /* unused */
-	8,
-	8,
-	8,
-	8,
-	8,
-	7,
-	7,
-	6,
-	6,
-	5
-};
-
-const uint8_t Zf(max_FG_bits)[] = {
-	0, /* unused */
-	8,
-	8,
-	8,
-	8,
-	8,
-	8,
-	8,
-	8,
-	8,
-	8
-};
