-		fpr fpct_d_re, fpct_d_im; \
-		fpr fpct_m; \
-		fpct_a_re = (a_re); \
-		fpct_a_im = (a_im); \
-		fpct_b_re = (b_re); \
-		fpct_b_im = (b_im); \
