-						_mm256_add_pd(x_im, y_im));
-					_mm256_storeu_pd(&f[j + ht].v,
-						_mm256_sub_pd(x_re, y_re));
-					_mm256_storeu_pd(&f[j + ht + hn].v,
-						_mm256_sub_pd(x_im, y_im));
-				}
-			} else {
-				fpr s_re, s_im;
-
-				s_re = fpr_gm_tab[((m + i1) << 1) + 0];
-				s_im = fpr_gm_tab[((m + i1) << 1) + 1];
-				for (j = j1; j < j2; j ++) {
-					fpr x_re, x_im, y_re, y_im;
