-/* see inner.h */
-TARGET_AVX2
-void
-Zf(iFFT)(fpr *f, unsigned logn)
-{
-	/*
-	 * Inverse FFT algorithm in bit-reversal order uses the following
-	 * iterative algorithm:
-	 *
-	 *   t = 1
-	 *   for m = N; m > 1; m /= 2:
-	 *       hm = m/2
-	 *       dt = t*2
-	 *       for i1 = 0; i1 < hm; i1 ++:
-	 *           j1 = i1 * dt
-	 *           s = iGM[hm + i1]
-	 *           for j = j1; j < (j1 + t); j ++:
-	 *               x = f[j]
-	 *               y = f[j + t]
-	 *               f[j] = x + y
-	 *               f[j + t] = s * (x - y)
-	 *       t = dt
-	 *   for i1 = 0; i1 < N; i1 ++:
-	 *       f[i1] = f[i1] / N
