-			/*
-			 * The value in sv should ultimately go to
-			 * address v, i.e. jump back by u-v slots.
-			 */
-			j = u - v;
-
-			/*
-			 * We increment v for the next iteration, but
-			 * only if the source value is valid. The mask
-			 * 'mk' is -1 if the value is valid, 0 otherwise,
-			 * so we _subtract_ mk.
-			 */
-			mk = (sv >> 15) - 1U;
-			v -= mk;
