-	hn = n >> 1;
-	t = hn;
-	for (u = 1, m = 2; u < logn; u ++, m <<= 1) {
-		size_t ht, hm, i1, j1;
-
-		ht = t >> 1;
-		hm = m >> 1;
-		for (i1 = 0, j1 = 0; i1 < hm; i1 ++, j1 += t) {
-			size_t j, j2;
-
-			j2 = j1 + ht;
