-					x_re = _mm256_loadu_pd(&f[j].v);
-					x_im = _mm256_loadu_pd(&f[j + hn].v);
-					y_re = _mm256_loadu_pd(&f[j+t].v);
-					y_im = _mm256_loadu_pd(&f[j+t + hn].v);
